package com.finstack.alert;
import com.finstack.alert.dto.AlertResponse; import com.finstack.user.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.security.authentication.*; import org.springframework.security.core.*; import org.springframework.security.core.context.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AlertService {private final AlertRepository alerts;private final UserRepository users;public AlertService(AlertRepository a,UserRepository u){alerts=a;users=u;}
 @Transactional(readOnly=true) public Page<AlertResponse> list(Boolean read,AlertType type,AlertSeverity severity,Pageable pageable){User u=user();Specification<Alert> s=(r,q,b)->b.equal(r.get("user").get("id"),u.getId());if(read!=null)s=s.and((r,q,b)->b.equal(r.get("read"),read));if(type!=null)s=s.and((r,q,b)->b.equal(r.get("alertType"),type));if(severity!=null)s=s.and((r,q,b)->b.equal(r.get("severity"),severity));return alerts.findAll(s,PageRequest.of(pageable.getPageNumber(),Math.min(100,Math.max(1,pageable.getPageSize())),pageable.getSort().isSorted()?pageable.getSort():Sort.by(Sort.Direction.DESC,"createdAt"))).map(AlertResponse::from);}
 @Transactional public void markRead(UUID id){Alert a=alerts.findByIdAndUserId(id,user().getId()).orElseThrow(AlertNotFoundException::new);a.markRead();alerts.save(a);} @Transactional public void markAllRead(){alerts.markAllReadByUserId(user().getId());}
 private User user(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||a instanceof AnonymousAuthenticationToken)throw new AuthenticationCredentialsNotFoundException("Authentication required");return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new AuthenticationCredentialsNotFoundException("User unavailable"));}}
